"""Load exact precompiled constants used by published task setup.

This helper changes material construction only. It does not alter the simulation,
model action, observation channels or verifier. Unknown materials fail explicitly.
"""
PRELUDE = "\nimport unreal_runtime as ur\nimport builtins as _paper_builtins\n_paper_material_specs = [['PixelMaterialInputs.BaseColor=float3(0.3,0.7,0.4);PixelMaterialInputs.Roughness=0.5;PixelMaterialInputs.OpacityMask=1.0;', ['DefaultLit', 'Masked', True], '/PaperRuntimeMaterials/Materials/M_908aa06ae2b0c0c3.M_908aa06ae2b0c0c3'], ['PixelMaterialInputs.BaseColor=float3(0.9,0.2,0.1);PixelMaterialInputs.Roughness=0.15;', ['DefaultLit', 'Masked', True], '/PaperRuntimeMaterials/Materials/M_20df90bc5ef6eeb4.M_20df90bc5ef6eeb4'], ['PixelMaterialInputs.EmissiveColor=float3(5.0,0.3,0.3);PixelMaterialInputs.BaseColor=float3(1.0,0.1,0.1);PixelMaterialInputs.Roughness=0.3;PixelMaterialInputs.OpacityMask=1.0;', ['DefaultLit', 'Masked', True], '/PaperRuntimeMaterials/Materials/M_127502014f57c69c.M_127502014f57c69c'], ['PixelMaterialInputs.BaseColor=float3(0.4,0.55,0.35);PixelMaterialInputs.Roughness=0.7;PixelMaterialInputs.OpacityMask=1.0;', ['DefaultLit', 'Masked', True], '/PaperRuntimeMaterials/Materials/M_a1fa9fc1a21ebc34.M_a1fa9fc1a21ebc34'], ['PixelMaterialInputs.BaseColor=float3(0.95,0.95,0.95);PixelMaterialInputs.Roughness=0.1;', ['DefaultLit', 'Masked', True], '/PaperRuntimeMaterials/Materials/M_5497943beb88560c.M_5497943beb88560c'], ['PixelMaterialInputs.EmissiveColor=float3(0.5,6.0,0.5);PixelMaterialInputs.BaseColor=float3(0.1,0.95,0.1);PixelMaterialInputs.Roughness=0.2;PixelMaterialInputs.OpacityMask=1.0;', ['DefaultLit', 'Masked', True], '/PaperRuntimeMaterials/Materials/M_11746c0e76330ce0.M_11746c0e76330ce0'], ['PixelMaterialInputs.BaseColor=float3(0.5,0.5,0.55);PixelMaterialInputs.Roughness=0.7;', ['DefaultLit', 'Opaque', False], '/PaperRuntimeMaterials/Materials/M_0ddb0ab778b4dcbb.M_0ddb0ab778b4dcbb'], ['PixelMaterialInputs.BaseColor=float3(0.1,0.3,0.9);PixelMaterialInputs.Roughness=0.3;', ['DefaultLit', 'Opaque', False], '/PaperRuntimeMaterials/Materials/M_75198f6ce39d0b6b.M_75198f6ce39d0b6b'], ['PixelMaterialInputs.BaseColor=float3(0.1,0.8,0.2);PixelMaterialInputs.Roughness=0.4;', ['DefaultLit', 'Opaque', False], '/PaperRuntimeMaterials/Materials/M_e7d3c2ca696fe4f1.M_e7d3c2ca696fe4f1'], ['PixelMaterialInputs.BaseColor=float3(0.9,0.1,0.05);PixelMaterialInputs.Roughness=0.2;PixelMaterialInputs.Metallic=0.5;', ['DefaultLit', 'Opaque', False], '/PaperRuntimeMaterials/Materials/M_739be32c00489704.M_739be32c00489704']]\nif not hasattr(_paper_builtins, '_veriworld_paper_materials'):\n    _paper_builtins._veriworld_paper_materials = {}\nclass _VeriWorldPaperMaterials:\n    def MakeSurfaceMaterialProperties(self, shading, blend, two_sided):\n        return [shading, blend, bool(two_sided)]\n    def CreateMaterialFromCodeAndWait(self, code, name, properties, timeout=30):\n        normalized = ''.join(code.split())\n        matches = [path for text,props,path in _paper_material_specs\n                   if text == normalized and props == list(properties)]\n        if len(matches) != 1:\n            raise RuntimeError('Material is outside the paper runtime preset set: '+name)\n        material = ur.StaticLoadObject(ur.Engine.MaterialInterface, None, matches[0])\n        if not material:\n            raise RuntimeError('Missing cooked paper material: '+matches[0])\n        _paper_builtins._veriworld_paper_materials[name] = matches[0]\n        return material\n    def GetRuntimeMaterial(self, name):\n        path = _paper_builtins._veriworld_paper_materials.get(name)\n        return ur.StaticLoadObject(ur.Engine.MaterialInterface, None, path) if path else None\n"

def rewrite_code(code):
    needle = 'ur.Engine.RuntimeMaterialLibrary'
    if needle not in code:
        return code
    return PRELUDE + '\n' + code.replace(needle, '_VeriWorldPaperMaterials()')
